// MapImage The image of a map document and its coordinate frame. Feature `pos` values are `[lat,
// lng]` in this frame, the frame the app uses when a feature is placed by clicking the map. A pixel
// `(x, y)` of the image, counted in pixels from its top-left corner, is at `pos = [north - y *
// (north - south) / height, west + x * (east - west) / width]`, which is `[-y / 2^z, x / 2^z]` with
// `z = ceil(log2(max(width, height) / 256))`. A `pos` converts back with `x = (lng - west) * width
// / (east - west)` and `y = (north - lat) * height / (north - south)`. The SDK exports this
// conversion as `pixelToPos` and `posToPixel`.
type MapImage struct {
	// AssetID The image asset in the project's library whose `url` is the map's image. null when no
	// image asset readable by the caller has that url: the asset was deleted, it is hidden and the
	// caller is not a project admin, or the map uses a legacy tiled map.
	AssetID opt.Nullable[string] `json:"assetId,omitzero"`
	// Bounds `[[south, west], [north, east]]`, the `[lat, lng]` corners the image covers. `north` and
	// `west` are 0 at the image's top-left corner; `south` is negative and `east` is positive.
	Bounds []json.RawMessage `json:"bounds"`
	// Height The image height in pixels.
	Height int64 `json:"height"`
	// Tiles The map's 256px image tiles. `urlTemplate` is a URL with `{z}`, `{x}` and `{y}`
	// placeholders; `maxNativeZoom` is the highest zoom with native tiles, `ceil(log2(max(width,
	// height) / 256))` and never below 0. null when the map has no image id.
	Tiles opt.Nullable[MapImageTiles] `json:"tiles,omitzero"`
	// URL The URL of the map's image. null for a legacy tiled map, which has no single image file.
	URL opt.Nullable[string] `json:"url,omitzero"`
	// Width The image width in pixels.
	Width int64 `json:"width"`
}

// MapImageTiles The map's 256px image tiles. `urlTemplate` is a URL with `{z}`, `{x}` and `{y}`
// placeholders; `maxNativeZoom` is the highest zoom with native tiles, `ceil(log2(max(width,
// height) / 256))` and never below 0. null when the map has no image id.
type MapImageTiles struct {
	MaxNativeZoom int64  `json:"maxNativeZoom"`
	URLTemplate   string `json:"urlTemplate"`
}

